else { echo '<section class="awsw-page"><div class="awsw-page-heading"><h1>'.esc_html(is_search()?awsw_theme_t('Search results','تلاش کے نتائج'):get_the_archive_title()).'</h1></div>';if(is_search()){get_search_form();}if(have_posts()){echo '<div class="awsw-grid">';while(have_posts()){the_post();echo '<article class="awsw-card awsw-card-body"><h2><a href="'.esc_url(function_exists('awsw_lang')?add_query_arg('lang',awsw_lang(),get_permalink()):get_permalink()).'">'.esc_html(function_exists('awsw_post_title')?awsw_post_title(get_the_ID()):get_the_title()).'</a></h2>';the_excerpt();echo '</article>';}echo '</div>';the_posts_pagination();}else{echo '<p>'.esc_html(awsw_theme_t('No results found. Try another search.','کوئی نتیجہ نہیں ملا۔ دوبارہ تلاش کریں۔')).'</p>';}echo '</section>'; }
